 @objc func synchronize(){
  guard remoteConnectionReady,let site=session,!remote.currentPath.isEmpty else{status.stringValue="请先连接服务器并读取目录";return}
  let choose=NSAlert();choose.messageText="同步当前目录";choose.informativeText="先比较并逐项预览。双向同步保留两侧独有文件；镜像以源端为准。时间、大小和内容比较可配置，清理目标端多余项目需明确选择。"
