     let preview=self.makeSyncPreview(candidates,localRoot:lp,remoteRoot:rp,localSnapshot:l,remoteSnapshot:r,deletions:deletions,site:site,socket:sock,policy:policy,comparisonSummary:settings.comparison.summary,requireUploadTimestamp:settings.comparison.modificationTime,timestampPlans:timestampPlans,retryContext:retryContext)
